class XMLCheck(HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=True);self.text=[];self.stack=[]
 def handle_starttag(self,tag,attrs):
  assert tag in {'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'},tag
  assert all(k in ('rowspan','colspan') and v.isdigit() for k,v in attrs),attrs
  if tag"'!='"'br':self.stack.append(tag)
 def handle_endtag(self,tag):assert self.stack.pop()==tag,tag
 def handle_data(self,data):self.text.append(data)
def txt(x):
